import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderServiceLegacy {
  private final OrderRepository orderRepo;
  private final EmailService emailService; // ❌ OLD: hard dependency

  @Transactional
  public void placeOrder(Order o) {
    orderRepo.save(o);
    // ❌ OLD: direct coupling — this service knows about EmailService
    // and calls it inline. Problems:
    // 1) If the transaction later rolls back, the email was ALREADY
    //    sent for an order that doesn't exist.
    // 2) Adding another subscriber (analytics, warehouse) means
    //    editing this method again.
    emailService.sendConfirmation(o); // ❌ OLD
  }
}

