import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.event.TransactionalEventListener;

// ✅ NEW: Publisher emits the event; listeners subscribe independently.
@Service
public class OrderService {
  private final OrderRepository orderRepo;
  private final ApplicationEventPublisher publisher;

  @Transactional
  public void placeOrder(Order o) {
    orderRepo.save(o);
    // ✅ NEW: just announce it — no knowledge of who cares
    publisher.publishEvent(new OrderPlacedEvent(o));
  }
}

// ✅ NEW: Separate listener bean — email only after COMMIT.
@Service
public class OrderNotificationListener {
  private final EmailService emailService;

  @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT) // ✅ NEW
  public void onOrderPlaced(OrderPlacedEvent e) {
    emailService.sendConfirmation(e.order()); // ✅ NEW: only if committed
  }
}

// record OrderPlacedEvent(Order order) {}

// For async listeners: add @Async to the method + @EnableAsync.
